// Match the actual triangles generated by buildWolfveilTerrain(), rather than
// sampling the analytical function between its 310x310 vertices. Those two
// surfaces can differ by several centimetres on curved terrain; small grass
// clumps and stones must sit on the visible mesh, not hover above it.
// Read-only sampling: no extra floor, BVH change or client-side authority.
import {wolfveilHeight} from './WolfveilLayout.js';

export function createWolfveilTerrainSurfaceSampler({span=1100,segments=310}={}){
  if(!Number.isFinite(span)||span<=0||!Number.isInteger(segments)||segments<2)
    throw new RangeError('Invalid Wolfveil terrain sampling dimensions');
  const step=span/segments,half=span/2;
  const heights=new Map();
  function at(ix,iz){
    const key=iz*(segments+1)+ix;
    if(!heights.has(key))
      heights.set(key,wolfveilHeight(ix*step-half,iz*step-half));
    return heights.get(key);
  }
  return function sample(x,z){
    if(!Number.isFinite(x)||!Number.isFinite(z))return null;
    // Outside the core mesh the meadow has its own sampler. Existing terrain
    // planting is inside the bounds, but guard this utility for other callers.
    if(Math.abs(x)>half||Math.abs(z)>half)return wolfveilHeight(x,z);
    const u=(x+half)/step,v=(z+half)/step;
    const ix=Math.min(segments-1,Math.max(0,Math.floor(u)));
    const iz=Math.min(segments-1,Math.max(0,Math.floor(v)));
    const fx=Math.max(0,Math.min(1,u-ix));
    const fz=Math.max(0,Math.min(1,v-iz));
    const a=at(ix,iz),b=at(ix,iz+1),c=at(ix+1,iz),d=at(ix+1,iz+1);
    // WolfveilGeometry triangles: (p,q,p+1) and (q,q+1,p+1).
    return fx+fz<=1
      ?a*(1-fx-fz)+b*fz+c*fx
      :b*(1-fx)+d*(fx+fz-1)+c*(1-fz);
  };
}
